package ch.jalu.configme.configurationdata;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import static org.mockito.ArgumentMatchers.anyList;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class CommentsConfigurationTest {

    @Mock
    private SettingsHolder settingsHolderMock;

    public List<String> getMockComments() {
        return new ArrayList<>();
    }

    @Test
    public void constructorCreatesCommentMapEmpty() {
        CommentsConfiguration comments = new CommentsConfiguration();
        assertNotNull(comments.getComments());
        assertEquals(0, comments.getComments().size());
    }

    @Test
    public void constructorSetsCommentMapFromMock() {
        CommentsConfiguration comments = new CommentsConfiguration(getMockComments());
        Mockito.when(settingsHolderMock.registerComments()).thenReturn(null);
        assertNotNull(comments);
        assertTrue(comments.getComments().contains(getMockComments()));
    }

    @Test
    public void setCommentSetsPathCommentsForGivenLines() {
        CommentsConfiguration comments = new CommentsConfiguration();
        List<String> commentLines = new ArrayList<>();
        commentLines.add("Line 1");
        commentLines.add("Line 2");
        comments.setComment("path", commentLines.get(0), commentLines.get(1));
        assertEquals(commentLines, comments.getComments().get("path"));
    }

    @Test
    public void setCommentOverwritesExistingCommentsForGivenPath() {
        CommentsConfiguration comments = new CommentsConfiguration();
        List<String> commentLines1 = new ArrayList<>();
        commentLines1.add("Line 1");
        commentLines1.add("Line 2");
        comments.setComment("path", commentLines1.get(0), commentLines1.get(1));
        List<String> commentLines2 = new ArrayList<>();
        commentLines2.add("Line 3");
        commentLines2.add("Line 4");
        comments.setComment("path", commentLines2.get(0), commentLines2.get(1));
        assertEquals(commentLines2, comments.getComments().get("path"));
    }

    @Test
    public void setCommentCreatesNewEntryIfNoExistingForGivenPath() {
        CommentsConfiguration comments = new CommentsConfiguration();
        List<String> commentLines = new ArrayList<>();
        commentLines.add("Line 3");
        commentLines.add("Line 4");
        comments.setComment("path", commentLines.get(0), commentLines.get(1));
        assertEquals(commentLines, comments.getComments().get("path"));
    }

    @Test
    public void setCommentDoesNotAddEmptyLineAsComment() {
        CommentsConfiguration comments = new CommentsConfiguration();
        List<String> commentLines = new ArrayList<>();
        String line = "\n";
        comments.setComment("path", line);
        assertEquals(0, comments.getComments().get("path").size());
    }

    @Test
    public void getAllCommentsReturnsUnmodifiableView() {
        CommentsConfiguration comments = new CommentsConfiguration();
        List<String> commentLines = new ArrayList<>();
        commentLines.add("Line 1");
        commentLines.add("Line 2");
        comments.setComment("path", commentLines.get(0), commentLines.get(1));
        Map<String, @UnmodifiableView List<String>> allComments = comments.getAllComments();
        assertTrue(allComments.containsKey("path"));
        assertFalse(allComments.get("path").isEmpty());
        assertEquals(commentLines, allComments.get("path"));
    }
}
